<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { AlertTriangle, CheckCircle2, CircleDot, Eye, FileWarning, Power, PowerOff, RadioTower, RefreshCw, RotateCcw, Server, WifiOff, Zap } from '@lucide/vue'
import { useRoute, useRouter } from 'vue-router'
import AppDataTable from '@/components/app/AppDataTable.vue'
import AppConfirmDialog from '@/components/app/AppConfirmDialog.vue'
import AppDrawer from '@/components/app/AppDrawer.vue'
import AppSelect from '@/components/app/AppSelect.vue'
import FilterBar from '@/components/app/FilterBar.vue'
import StatusTag from '@/components/app/StatusTag.vue'
import { useAlertRef } from '@/composables/useAppAlert'
import { access, replayAccessRawMessage, sendAccessCommand, sendCommand } from '@/api/platform'
import { unwrapRemote } from '@/api/http'
import type { RecordRow } from '@/types/domain'
import { accessLabel, onlineLabel } from '@/utils/enumLabels'

const route=useRoute(),router=useRouter(),mode=computed(()=>String(route.meta.kind))
const loading=ref(false),error=useAlertRef(),rows=ref<RecordRow[]>([]),payload=ref<RecordRow>({}),selected=ref<RecordRow|null>(null)
const confirmOpen=ref(false),confirmBusy=ref(false),confirmTitle=ref(''),confirmMessage=ref(''),pendingAction=ref<(()=>Promise<void>)|null>(null)
const onlineStatus=ref(''),keyword=ref(''),gatewayId=ref(''),targetId=ref(''),commandStatus=ref(''),detailTab=ref<'discovered'|'raw'>('discovered')
const targets=computed(()=>payload.value.targets&&typeof payload.value.targets==='object'?payload.value.targets as RecordRow:{})
const gateways=computed(()=>Array.isArray(targets.value.gateways)?targets.value.gateways as RecordRow[]:[])
const devices=computed(()=>Array.isArray(targets.value.devices)?targets.value.devices as RecordRow[]:[])
const selectedDevice=computed(()=>devices.value.find(x=>String(x.id)===targetId.value)||devices.value[0]||null)
const discovered=computed(()=>Array.isArray(payload.value.discovered)?payload.value.discovered as RecordRow[]:[])
const rawMessages=computed(()=>Array.isArray(payload.value.raw)?payload.value.raw as RecordRow[]:[])
const onlineCount=computed(()=>rows.value.filter(x=>String(x.status).toUpperCase()==='ONLINE').length)
const offlineCount=computed(()=>Math.max(0,rows.value.length-onlineCount.value))
const pendingCount=computed(()=>discovered.value.filter(x=>String(x.discoveryStatus).toUpperCase()!=='BOUND').length)
const errorCount=computed(()=>rawMessages.value.filter(x=>['INVALID','MQ_FAILED'].includes(String(x.status).toUpperCase())).length)
const lastReceive=computed(()=>rawMessages.value.map(x=>String(x.receiveTime||x.receive_time||'')).filter(Boolean).sort().at(-1)||'暂无记录')
const healthTone=computed(()=>!rows.value.length?'muted':offlineCount.value===0&&errorCount.value===0?'good':'warn')
const healthText=computed(()=>healthTone.value==='good'?'链路运行正常':healthTone.value==='warn'?'存在待处理异常':'暂无接入数据')
const rawColumns=[{key:'gatewaySn',label:'网关编号'},{key:'receiveTime',label:'接收时间'},{key:'messageType',label:'报文类型'},{key:'status',label:'解析状态'},{key:'failReason',label:'异常原因'}]
const discoveryColumns=[{key:'deviceSn',label:'发现设备'},{key:'gatewayId',label:'来源网关'},{key:'protocolAddr',label:'协议地址'},{key:'seenCount',label:'上报次数'},{key:'lastSeenTime',label:'最近发现'},{key:'discoveryStatus',label:'接入状态'}]
const commandColumns=[{key:'target_sn',label:'目标编号'},{key:'command_type',label:'指令类型'},{key:'request_username',label:'发起人'},{key:'request_time',label:'发起时间'},{key:'response_time',label:'响应时间'},{key:'status',label:'执行状态'},{key:'fail_reason',label:'失败原因'}]
const text=(v:unknown)=>String(v??'').trim()
const queryText=(v:unknown)=>Array.isArray(v)?text(v[0]):text(v)
function syncQuery(){gatewayId.value=queryText(route.query.gatewayId);targetId.value=queryText(route.query.targetId||route.query.deviceId)}
async function load(){loading.value=true;error.value='';try{if(mode.value==='access'){const[g,r,d]=await Promise.all([access('gateways/status'),access('raw-messages'),access('discovered-devices')]);const list=unwrapRemote(g) as unknown as RecordRow[];payload.value={raw:unwrapRemote(r),discovered:unwrapRemote(d)};rows.value=(Array.isArray(list)?list:[]).filter(x=>!onlineStatus.value||text(x.status).toUpperCase()===onlineStatus.value);return}const[p,t]=await Promise.all([access('commands/page',{pageNum:1,pageSize:50,keyword:keyword.value||undefined,gatewayId:gatewayId.value||undefined,targetId:targetId.value||undefined,status:commandStatus.value||undefined}),access('command-targets')]);payload.value={targets:unwrapRemote(t)};rows.value=(p as unknown as{records?:RecordRow[]}).records||[]}catch(e){rows.value=[];error.value=e instanceof Error?e.message:'接入诊断读取失败'}finally{loading.value=false}}
function onboard(row:RecordRow){router.push({path:'/device-archive/devices',query:{discoveryId:text(row.id),deviceSn:text(row.deviceSn),gatewayId:text(row.gatewayId),protocolAddr:text(row.protocolAddr),rawLogId:text(row.latestRawLogId)}})}
async function openRaw(row:RecordRow){try{selected.value=unwrapRemote(await access(`raw-messages/${row.id}`)) as RecordRow}catch(e){error.value=e instanceof Error?e.message:'报文详情读取失败'}}
async function replay(){if(!selected.value?.id)return;try{await replayAccessRawMessage(selected.value.id);selected.value=null;await load()}catch(e){error.value=e instanceof Error?e.message:'报文重放失败'}}
function askCommand(title:string,message:string,action:()=>Promise<void>){confirmTitle.value=title;confirmMessage.value=message;pendingAction.value=action;confirmOpen.value=true}
async function confirmCommand(){if(!pendingAction.value)return;confirmBusy.value=true;try{await pendingAction.value();confirmOpen.value=false}finally{confirmBusy.value=false;pendingAction.value=null}}
function reboot(row:RecordRow){const id=row.id;if(!id)return;const name=text(row.gatewayName||row.gatewaySn||row.gateway_name||row.gateway_sn);askCommand('确认重启网关',`即将向“${name}”下发重启指令。网关重启期间，该网关下的设备可能暂时无法采集数据。`,async()=>{try{await sendAccessCommand({gatewayId:Number(id),targetId:Number(id),targetType:'GATEWAY',targetSn:row.gatewaySn||row.gateway_sn,commandType:'REBOOT_GATEWAY',commandPayload:{}});await load()}catch(e){error.value=e instanceof Error?e.message:'网关重启失败'}})}
function deviceCommand(commandType:string,commandPayload:RecordRow,label:string){if(!selectedDevice.value?.id)return;const name=text(selectedDevice.value.device_name||selectedDevice.value.deviceName||selectedDevice.value.device_sn||selectedDevice.value.deviceSn);askCommand(`确认${label}`,`即将向设备“${name}”下发“${label}”命令，请确认现场设备允许执行该操作。`,async()=>{try{selected.value=await sendCommand({targetId:Number(selectedDevice.value?.id),commandType,commandPayload});await load()}catch(e){error.value=e instanceof Error?e.message:'设备指令下发失败'}})}
watch(()=>route.fullPath,()=>{syncQuery();void load()});onMounted(()=>{syncQuery();void load()})
</script>

<template><section class="view-page access-page"><header class="view-head access-head"><div><p class="eyebrow">ACCESS DIAGNOSTICS</p><h1>{{mode==='access'?'接入诊断':mode==='control'?'设备控制台':'指令记录'}}</h1><small>从网关心跳、设备发现到原始报文，定位数据进入平台前的每一个环节。</small></div><button class="quiet" :disabled="loading" @click="load"><RefreshCw :size="15" :class="{spinning:loading}"/>刷新</button></header>
<template v-if="mode==='access'"><section class="diagnostic-summary"><article class="summary-status" :class="healthTone"><span class="summary-icon"><CheckCircle2 v-if="healthTone==='good'" :size="19"/><AlertTriangle v-else-if="healthTone==='warn'" :size="19"/><RadioTower v-else :size="19"/></span><div><span>当前接入结论</span><strong>{{healthText}}</strong><small>最近报文：{{lastReceive}}</small></div></article><article><span>在线网关</span><strong>{{onlineCount}}<small>/ {{rows.length}}</small></strong><em><CircleDot :size="12"/>{{offlineCount?`${offlineCount} 台离线`:'全部在线'}}</em></article><article><span>待登记设备</span><strong>{{pendingCount}}</strong><em><Server :size="12"/>发现后进入设备档案</em></article><article><span>异常报文</span><strong>{{errorCount}}</strong><em><FileWarning :size="12"/>解析或转发失败</em></article></section>
<section class="diagnostic-main"><article class="panel gateway-panel"><div class="section-head"><div><p>GATEWAY HEALTH</p><h2>网关健康矩阵</h2><small>按最近心跳和报文接收状态判断。</small></div><AppSelect v-model="onlineStatus" class="status-filter" @change="load"><option value="">全部状态</option><option value="ONLINE">在线</option><option value="OFFLINE">离线</option></AppSelect></div><div class="gateway-grid"><article v-for="gateway in rows" :key="String(gateway.id||gateway.gatewaySn)" class="gateway-card"><div class="gateway-card-head"><span class="status-light" :class="text(gateway.status).toLowerCase()"></span><b>{{gateway.gatewayName||gateway.gatewaySn||gateway.gateway_name||gateway.gateway_sn||'未命名网关'}}</b><span>{{onlineLabel(gateway.status)}}</span></div><dl><div><dt>网关编号</dt><dd>{{gateway.gatewaySn||gateway.gateway_sn||'—'}}</dd></div><div><dt>最近在线</dt><dd>{{gateway.lastSeenTime||gateway.last_seen_time||'—'}}</dd></div></dl><button type="button" @click="reboot(gateway)"><RotateCcw :size="13"/>重启网关</button></article><div v-if="!rows.length" class="empty-state">当前授权范围暂无网关状态。</div></div></article><aside class="panel diagnosis-panel"><div class="section-head"><div><p>DIAGNOSIS GUIDE</p><h2>排查建议</h2><small>先看链路位置，再处理异常对象。</small></div><WifiOff :size="19"/></div><div class="steps"><div><i>1</i><span><b>网关离线</b><small>检查心跳时间、电源和 MQTT 连接。</small></span></div><div><i>2</i><span><b>设备待登记</b><small>确认协议地址后完成设备档案绑定。</small></span></div><div><i>3</i><span><b>报文异常</b><small>查看原始报文，必要时重放验证。</small></span></div></div></aside></section>
<section class="panel evidence-panel"><div class="evidence-tabs"><button :class="{active:detailTab==='discovered'}" @click="detailTab='discovered'"><Server :size="14"/>待登记设备 <em>{{pendingCount}}</em></button><button :class="{active:detailTab==='raw'}" @click="detailTab='raw'"><FileWarning :size="14"/>原始报文 <em>{{rawMessages.length}}</em></button></div><AppDataTable v-if="detailTab==='discovered'" :columns="discoveryColumns" :rows="discovered" :loading="loading" :error="error" empty-text="暂无待登记设备"><template #cell-discoveryStatus="{value}"><span class="tag" :class="String(value)==='BOUND'?'success':'warn'">{{accessLabel(value)}}</span></template><template #actions="{row}"><button class="link-btn" @click="String(row.discoveryStatus)==='BOUND'?selected=row:onboard(row)">{{String(row.discoveryStatus)==='BOUND'?'查看绑定':'进入设备登记'}}</button></template></AppDataTable><AppDataTable v-else :columns="rawColumns" :rows="rawMessages" :loading="loading" :error="error" empty-text="暂无原始报文"><template #cell-status="{value}"><span class="tag" :class="String(value)==='FORWARDED'?'success':['INVALID','MQ_FAILED'].includes(String(value))?'danger':'warn'">{{accessLabel(value)}}</span></template><template #actions="{row}"><button class="link-btn" @click="openRaw(row)"><Eye :size="14"/>详情</button></template></AppDataTable></section></template>
<template v-else><section v-if="mode==='control'" class="panel control-strip"><label><span>控制设备</span><AppSelect v-model="targetId"><option v-for="x in devices" :key="String(x.id)" :value="String(x.id)">{{x.device_name||x.deviceName||x.device_sn||x.deviceSn}}</option></AppSelect></label><div><button class="primary" @click="deviceCommand('DEVICE_COMMAND',{commandCode:'BREAKER_CLOSE'},'合闸')"><Power :size="14"/>合闸</button><button class="quiet" @click="deviceCommand('DEVICE_COMMAND',{commandCode:'BREAKER_OPEN'},'分闸')"><PowerOff :size="14"/>分闸</button><button class="quiet" @click="deviceCommand('READ_NOW',{},'立即读取')"><Zap :size="14"/>立即读取</button></div></section><FilterBar v-model:keyword="keyword" :busy="loading" placeholder="目标编号或指令类型" @query="load" @reset="()=>{keyword='';gatewayId='';targetId='';commandStatus='';load()}"><label class="field inline"><span>网关</span><AppSelect v-model="gatewayId"><option value="">全部网关</option><option v-for="x in gateways" :key="String(x.id)" :value="String(x.id)">{{x.gateway_name||x.gateway_sn}}</option></AppSelect></label><label class="field inline"><span>执行状态</span><AppSelect v-model="commandStatus"><option value="">全部</option><option value="2">成功</option><option value="3">失败</option><option value="4">超时</option></AppSelect></label></FilterBar><AppDataTable :columns="commandColumns" :rows="rows" :loading="loading" :error="error"><template #cell-status="{value}"><StatusTag domain="command" :value="value"/></template></AppDataTable></template>
<AppDrawer :open="Boolean(selected)" title="接入证据详情" @update:open="open=>{if(!open)selected=null}"><div class="drawer-actions"><button v-if="selected?.payload" class="primary" @click="replay"><RefreshCw :size="14"/>重放报文</button></div><pre>{{JSON.stringify(selected,null,2)}}</pre></AppDrawer><AppConfirmDialog :open="confirmOpen" eyebrow="COMMAND CONFIRM" :title="confirmTitle" :message="confirmMessage" confirm-text="确认发送" cancel-text="取消" :loading="confirmBusy" @update:open="value=>{confirmOpen=value;if(!value)pendingAction=null}" @confirm="confirmCommand"/></section></template>

<style scoped>
.access-page{height:100%;min-height:0;display:flex;flex-direction:column;gap:12px;overflow:hidden}.access-head{margin:0;flex:none}.access-head small{display:block;margin-top:4px;color:var(--muted);font-size:11px}.diagnostic-summary{display:grid;grid-template-columns:1.6fr repeat(3,1fr);gap:10px;flex:none}.diagnostic-summary>article{min-width:0;padding:13px 15px;border:1px solid var(--border);border-radius:8px;background:#fff}.diagnostic-summary>article:not(.summary-status){display:grid;gap:6px}.diagnostic-summary span{color:var(--muted);font-size:10px}.diagnostic-summary strong{display:block;color:#203b57;font-size:24px;line-height:1.1}.diagnostic-summary strong small{font-size:11px}.diagnostic-summary em{display:flex;align-items:center;gap:4px;color:var(--muted);font-style:normal;font-size:10px}.summary-status{display:flex;align-items:center;gap:10px}.summary-icon{width:34px;height:34px;display:grid;place-items:center;border-radius:8px;background:#eaf7ef;color:#258b5b}.warn .summary-icon{background:#fff3df;color:#bd7b20}.muted .summary-icon{background:#f1f4f7;color:#718398}.summary-status div{display:grid;gap:3px}.summary-status strong{font-size:15px}.diagnostic-main{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(270px,.7fr);gap:12px;min-height:0}.gateway-panel,.diagnosis-panel,.evidence-panel{padding:14px}.section-head{display:flex;justify-content:space-between;gap:12px}.section-head p{margin:0;color:var(--accent);font:700 9px ui-monospace,monospace;letter-spacing:1px}.section-head h2{margin:3px 0;font-size:15px}.section-head small{color:var(--muted);font-size:10px}.status-filter{width:110px}.gateway-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:11px;max-height:220px;overflow:auto}.gateway-card{padding:10px;border:1px solid #dbe6ef;border-radius:6px;background:#fbfdff}.gateway-card-head{display:flex;align-items:center;gap:7px}.gateway-card-head b{min-width:0;flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px}.gateway-card-head>span:last-child{color:var(--muted);font-size:9px}.status-light{width:8px;height:8px;border-radius:50%;background:#d85f4d}.status-light.online{background:#24ae78;box-shadow:0 0 0 3px #e5f7ee}.gateway-card dl{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:9px 0}.gateway-card dt{color:var(--muted);font-size:9px}.gateway-card dd{margin:2px 0 0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10px}.gateway-card button{display:inline-flex;align-items:center;gap:4px;padding:4px 7px;border:1px solid #d8e4ed;border-radius:4px;background:#fff;color:#597087;font-size:9px}.steps{display:grid;margin-top:10px}.steps>div{display:flex;gap:8px;padding:10px 0;border-bottom:1px solid var(--border)}.steps i{width:21px;height:21px;display:grid;place-items:center;border-radius:50%;background:#edf5fb;color:var(--accent);font:700 10px ui-monospace}.steps span{display:grid;gap:2px}.steps b{font-size:10px}.steps small{color:var(--muted);font-size:9px}.evidence-panel{display:flex;flex:1;min-height:0;flex-direction:column;overflow:hidden}.evidence-tabs{display:flex;flex:none;gap:3px;margin:-14px -14px 10px;padding:0 10px;border-bottom:1px solid var(--border)}.evidence-tabs button{height:37px;display:inline-flex;align-items:center;gap:5px;padding:0 10px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);font-size:10px}.evidence-tabs button.active{border-bottom-color:var(--accent);color:var(--accent);font-weight:700}.evidence-tabs em{padding:2px 5px;border-radius:9px;background:#edf4fa;font-style:normal;font-size:9px}.evidence-panel :deep(.app-table),.evidence-panel :deep(.data-content){flex:1;min-height:0;display:flex;flex-direction:column;margin:0}.evidence-panel :deep(.table-scroll){flex:1;min-height:0;overflow:auto}.drawer-actions{display:flex;justify-content:flex-end;margin:0 25px 8px}.drawer-actions button,.link-btn{display:inline-flex;align-items:center;gap:4px}.spinning{animation:spin .8s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}@media(max-width:980px){.diagnostic-summary{grid-template-columns:repeat(2,1fr)}.summary-status{grid-column:1/-1}.diagnostic-main{grid-template-columns:1fr}}@media(max-width:680px){.access-page{height:auto;overflow:visible}.diagnostic-summary{grid-template-columns:1fr}.summary-status{grid-column:auto}.gateway-grid{grid-template-columns:1fr;max-height:none}}
</style>
